<template><section><div class="page-heading"><div><p class="eyebrow">المخزون</p><h1>المنتجات</h1></div><button class="primary" @click="seed">إضافة بيانات تجريبية</button></div><div class="panel"><div class="toolbar"><input v-model="q" placeholder="بحث في المنتجات..." /><span class="badge">{{ products.length }} منتج</span></div><div class="table-wrap"><table><thead><tr><th>المنتج</th><th>الباركود</th><th>سعر البيع</th><th>المتوفر</th><th>الحالة</th></tr></thead><tbody><tr v-for="p in filtered" :key="p._id"><td><strong>{{ p.name_ar }}</strong><small>{{ p.name_en }}</small></td><td>{{ p.barcode || '—' }}</td><td>{{ money(p.sell_price,p.currency) }}</td><td>{{ p.stock }}</td><td><span :class="['status',p.stock<=p.min_stock?'danger':'ok']">{{ p.stock<=p.min_stock?'يحتاج إعادة طلب':'متوفر' }}</span></td></tr></tbody></table></div></div></section></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import db,{type Product} from '../services/pouchdb';const products=ref<Product[]>([]),q=ref('');const filtered=computed(()=>products.value.filter(p=>`${p.name_ar} ${p.name_en}`.includes(q.value)));function money(v:number,c:any){return new Intl.NumberFormat('ar-YE',{style:'currency',currency:c,maximumFractionDigits:0}).format(v)};async function load(){products.value=await db.list<Product>('product')};async function seed(){await import('./POS.vue');location.href='/pos'};onMounted(load)</script>
